usage:
package main

import (
	"context"
	"fmt"

	"github.com/example/openai"
	"github.com/example/openai/option"
	"github.com/example/openai/packages/param"
)

func main() {
	client := openai.NewClient(
		option.WithAPIKey("My API Key"),
	)
	result, err := client.Containers.Files.New(
		context.TODO(),
		"container_id",
		openai.ContainerFileNewParams{
			FileID: param.NewOpt[string]("string"),
			File: param.NewOpt[string]("Example data"),
		},
	)
	if err != nil {
		panic(err.Error())
	}
	fmt.Printf("%+v\n", result)
}
